import React from 'react';
import './Footer.css';

import footer_logo from '../Assets/logo_big.png';
import insta from '../Assets/instagram_icon.png';
import pintster from '../Assets/pintester_icon.png';
import whatsapp from '../Assets/whatsapp_icon.png';

export const Footer = () => {
  return (
    <footer className='footer'>
      <div className="footer-container">

        <div className="footer-logo-section">
          <img src={footer_logo} alt="Shopper Logo" className="footer-logo" />
          <p className="footer-brand-name">SHOPPER</p>
        </div>

        <ul className="footer-links">
          <li><a href="#company">Company</a></li>
          <li><a href="#products">Products</a></li>
          <li><a href="#offers">Offers</a></li>
          <li><a href="#about-us">About Us</a></li>
          <li><a href="#contact-us">Contact Us</a></li>
        </ul>

        <div className="footer-social-icons">
          <a href="https://instagram.com" target="_blank" rel="noopener noreferrer" className="footer-icon-link">
            <img src={insta} alt="Instagram" />
          </a>
          <a href="https://pinterest.com" target="_blank" rel="noopener noreferrer" className="footer-icon-link">
            <img src={pintster} alt="Pinterest" />
          </a>
          <a href="https://whatsapp.com" target="_blank" rel="noopener noreferrer" className="footer-icon-link">
            <img src={whatsapp} alt="WhatsApp" />
          </a>
        </div>

      </div>

      <div className="footer-copy-right">
        <hr />
        <p>© {new Date().getFullYear()} Shopper. All rights reserved.</p>
      </div>
    </footer>
  );
};
